#include "StdAfx.h"#include "KeybCOM.h"#include ".\PipeUprawl.h"#include "LogFile.h"//extern UINT nMessageKeyboard;//CPipeUprawl::CPipeUprawl(): CPipeSerS( "PipeUprawl", 32, 32 )  {  }CPipeUprawl::~CPipeUprawl(void)  {  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int CPipeUprawl::Action()  {  //  // Читаем код запроса  DWORD dwCode = 0;  DWORD dwRead = 0;  ReadFile( m_hPipe, &dwCode, sizeof(DWORD), &dwRead, NULL);  if ( dwRead != sizeof(DWORD) )    return -1;  BOOL fSuccess;  fSuccess = ReadFile( m_hPipe, &u, sizeof(u), &dwRead, NULL);  if (! fSuccess || dwRead != sizeof(u))     return -1;  //  memset( &input, 0, sizeof(INPUT) );  //  switch ( u.uMsg )	  {    //    case WM_KEYDOWN:      Keyboard();      break;    case WM_CHAR:      return 0;    case WM_KEYUP:      Keyboard();      input.ki.dwFlags = KEYEVENTF_KEYUP;      break;    //    case WM_LBUTTONDOWN : Mouse(MOUSEEVENTF_LEFTDOWN ); break;    case WM_LBUTTONUP   : Mouse(MOUSEEVENTF_LEFTUP   ); break;    case WM_RBUTTONDOWN : Mouse(MOUSEEVENTF_RIGHTDOWN); break;    case WM_RBUTTONUP   : Mouse(MOUSEEVENTF_RIGHTUP  ); break;    case WM_MOUSEMOVE   : Mouse(MOUSEEVENTF_ABSOLUTE);      ::SetCursorPos(input.mi.dx,input.mi.dy);      return 0;    //    case WM_USER+1:      {      ::PostMessage( HWND_BROADCAST, nMessageKeyboard, u.wParam, u.lParam );      return 0;      }      break;    default:      ::PostMessage( HWND_BROADCAST, u.uMsg, u.wParam, u.lParam );      return 0;	  }  //  CLogFile::Log ("SendInput (Action): input.ki.dwFlags %08lx", input.ki.dwFlags);  SendInput(1, &input, sizeof(INPUT));  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void CPipeUprawl::Mouse(DWORD dw)  {  input.type = INPUT_MOUSE;  input.mi.dx = LOWORD( u.lParam );  input.mi.dy = HIWORD( u.lParam );  input.mi.dwFlags = dw;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void CPipeUprawl::Keyboard()  {  input.type = INPUT_KEYBOARD;  input.ki.wVk   = LOWORD(u.wParam);  input.ki.wScan = MapVirtualKey(LOWORD(u.wParam), 0);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~